const updateCloudflareConnection = `-- name: UpdateCloudflareConnection :one
UPDATE cloudflare_connections
SET account_id = ?, account_name = ?, token = ?, status = 'ok', status_reason = '', updated_at = ?, updated_by = ?
WHERE id = +?
RETURNING id, name, account_id, account_name, token, status, status_reason, created_at, updated_at, updated_by
`

type UpdateCloudflareConnectionParams struct {
	AccountID   string
	AccountName string
	Token       []byte
	UpdatedAt   time.Time
	UpdatedBy   string
	ID          int64
}

// A new token (checked): the connection works again.
func (q *Queries) UpdateCloudflareConnection(ctx context.Context, arg UpdateCloudflareConnectionParams) (CloudflareConnection, error) {
	row := q.db.QueryRowContext(ctx, updateCloudflareConnection,
		arg.AccountID,
		arg.AccountName,
		arg.Token,
		arg.UpdatedAt,
		arg.UpdatedBy,
		arg.ID,
	)
	var i CloudflareConnection
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.AccountID,
		&i.AccountName,
		&i.Token,
		&i.Status,
		&i.StatusReason,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedBy,
	)
	return i, err
}

